// lib/sites/youtube/features/watch/metadata-update.ts
//
// Parses live view-count / date updates pushed by YouTube through the
// /youtubei/v1/updated_metadata fetch interceptor. Pure: callers decide what
// to do with the extracted strings.
//
// YouTube ships these updates in two shapes (generated by quicktype into
// ../../types/VideoData as `UpdatedMetadata`):
//  1. Legacy `actions[]` with `updateViewershipAction` / `updateDateTextAction`,
//     which is how logged-out sessions receive the view count.
//  2. `frameworkUpdates.entityBatchUpdate.mutations[]`, each carrying a
//     `payload.viewCountEntity`, which is how logged-in sessions receive it.
//
// The two can arrive in the SAME payload: a logged-in VOD sends its date text
// through `actions` while the view count rides in `frameworkUpdates`, so the
// parser merges both rather than preferring one over the other.
//
// The generated types describe the samples we captured, but a live payload can
// be thinner, so every level below is guarded anyway.

import type {
  UpdatedMetadataAction,
  UpdatedMetadataFrameworkUpdates,
  UpdateDateTextAction,
  UpdateViewershipAction,
} from "../../types/VideoData";

export interface MetadataUpdate {
  viewCount?: string;
  dateText?: string;
  exactCount?: number;
}

/** The subset of the response the parser reads; a real payload carries more. */
export interface MetadataPayload {
  actions?: UpdatedMetadataAction[];
  frameworkUpdates?: UpdatedMetadataFrameworkUpdates;
}

/** A `{ simpleText }` / `{ runs }` text node: the two shapes YouTube uses. */
interface TextLike {
  simpleText?: string;
  runs?: Array<{ text: string }>;
}

function textOf(value: TextLike | undefined): string | undefined {
  if (!value) return undefined;
  if (value.simpleText) return value.simpleText;
  const joined = value.runs?.map((run) => run.text).join("");
  return joined ? joined : undefined;
}

function parseExactCount(original: string | undefined): number | undefined {
  if (!original) return undefined;
  const parsed = Number.parseInt(original, 10);
  return Number.isNaN(parsed) ? undefined : parsed;
}

/** Parses the legacy `actions[]` payload. */
export function parseMetadataActions(
  actions: UpdatedMetadataAction[],
): MetadataUpdate | null {
  const viewership: UpdateViewershipAction | undefined = actions.find(
    (action) => action.updateViewershipAction,
  )?.updateViewershipAction;
  const dateTextAction: UpdateDateTextAction | undefined = actions.find(
    (action) => action.updateDateTextAction,
  )?.updateDateTextAction;

  const renderer = viewership?.viewCount?.videoViewCountRenderer;

  const viewCountString = textOf(renderer?.viewCount);
  const dateTextString = textOf(dateTextAction?.dateText);
  const exactCount = parseExactCount(renderer?.originalViewCount);

  if (!viewCountString && !dateTextString) return null;

  return {
    ...(viewCountString ? { viewCount: viewCountString } : {}),
    ...(dateTextString ? { dateText: dateTextString } : {}),
    ...(exactCount !== undefined ? { exactCount } : {}),
  };
}

/** Parses the `frameworkUpdates.entityBatchUpdate` payload. */
export function parseFrameworkUpdates(
  frameworkUpdates: MetadataPayload["frameworkUpdates"],
): MetadataUpdate | null {
  const mutations = frameworkUpdates?.entityBatchUpdate?.mutations;
  if (!Array.isArray(mutations)) return null;

  for (const mutation of mutations) {
    const entity = mutation?.payload?.viewCountEntity;
    if (!entity) continue;

    // `viewCount` holds the full string ("1,486 watching now" / "5,219
    // views"); `shortViewCount` is only a fallback. Logged-in VODs also ship
    // `viewCountNumber`, a locale-independent exact count.
    const viewCount = textOf(entity.viewCount) ?? textOf(entity.shortViewCount);
    const exactCount = parseExactCount(entity.viewCountNumber);
    if (!viewCount && exactCount === undefined) continue;

    return {
      ...(viewCount ? { viewCount } : {}),
      ...(exactCount !== undefined ? { exactCount } : {}),
    };
  }

  return null;
}

/** Parses whichever update shape YouTube sent (possibly both at once). */
export function parseMetadataUpdate(
  detail: MetadataPayload,
): MetadataUpdate | null {
  const fromActions = Array.isArray(detail.actions)
    ? parseMetadataActions(detail.actions)
    : null;
  const fromFramework = parseFrameworkUpdates(detail.frameworkUpdates);

  // A logged-in VOD splits its update: date text in `actions`, view count in
  // `frameworkUpdates`. Merge so neither half is dropped; `actions` wins any
  // field it also provides.
  const merged: MetadataUpdate = { ...fromFramework, ...fromActions };
  return Object.keys(merged).length > 0 ? merged : null;
}
